                try(print(apply(input_df_red_out[input_df_red_full$time_id %in%
                  times_out[1]:(max(times_out) + nTimesLookahead),
                  dataInputs_colnames_past], 2, function(zer) {
                  mean(zer, na.rm = T)
                })), T)
                try(print(apply(input_df_red_out[input_df_red_full$time_id %in%
                  times_out[1]:(max(times_out) + nTimesLookahead),
                  dataInputs_colnames_past], 2, function(zer) {
