                        pch_ <- (np$array(hat_y$y_mu)[, , 1])
                        pch_[] <- 1:nrow(pch_)
                        pch_
                      }), main = "Outcome")
                    abline(a = 0, b = 1)
                    cor(x_, y_)
                    plot(c(np$array(hat_y$y_mu)[, , 2]), np$array(jax_batchy)[1,
                      , 2], main = "Policy")
                    abline(a = 0, b = 1)
                    summary(lm(c(np$array(hat_y$y_mu)[, , 1]) ~
                      c(np$array(jax_batchy)[1, , , 1])))
                    summary(lm(c(np$array(hat_y$y_mu)[, , 2]) ~
                      c(np$array(jax_batchy)[1, , , 2])))
