                        , 1], file = "~/Downloads/in_x1_MultiDisease.csv")
                      write.csv(np$array(jax_batchx[[1]][[1]])[,
                        , 2], file = "~/Downloads/in_x2_MultiDisease.csv")
                      write.csv(np$array(jax_batchx[[1]][[1]])[,
                        , 3], file = "~/Downloads/in_x3_MultiDisease.csv")
                      write.csv(np$array(hat_y$y_mu)[, , 1],
