                      }
                      return(ret_)
                    })
                  drop_indicator <- (mean(results_by_anchor["XPred_mask",
                    ][[1]]) < MIN_NA_ACCEPT_FRAC)
                  if (!is.null(finalGenLocID)) {
                    ii_ <- ii_ + 1
                  }
