                    eval(parse(text = sprintf("\n                    %s_samp <- %s( jnp$take(localze,indices = jnp$array(tmp_i <- (ai(which(lDepParamsVec_ %%in%% c(uq_encneural_vec, 'Neural1'))-1L))), axis=0L) )\n                ",
