                    drop = FALSE])
                }
            }
            row.names(DiffImport) <- gsub(row.names(DiffImport),
                pattern = "_Decoder", replace = "")
            row.names(DecoderImport) <- gsub(row.names(DecoderImport),
                pattern = "_Decoder", replace = "")
            row.names(NeuralODEImport) <- gsub(row.names(NeuralODEImport),
