.ndm_run_impl_expr <- expression(`%||%` <- function(x, y) {
    if (is.null(x)) {
        return(y)
    }
    x
}, analysis2_internal_analysis_root <- function() {
    analysis_root <- get0("NDM_PACKAGE_ANALYSIS_ROOT", inherits = TRUE,
        ifnotfound = NULL)
    if (is.null(analysis_root) || !nzchar(analysis_root)) {
        stop("`NDM_PACKAGE_ANALYSIS_ROOT` must be defined before sourcing Analysis2_api.R.",
            call. = FALSE)
    }
    normalizePath(analysis_root, winslash = "/", mustWork = TRUE)
}, analysis2_log <- function(text) {
    message(sprintf("[%s] %s", format(Sys.time(), "%Y-%m-%d %H:%M:%S"),
        text))
    invisible(text)
}, analysis2_f2n <- function(x) {
    as.numeric(as.character(x))
}, analysis2_as_int <- function(x) {
    as.integer(round(analysis2_f2n(x)))
}, analysis2_small_run_n_checkpoints <- function(n_samples_train,
    n_sgd, default = 10L) {
    n_samples <- analysis2_as_int(n_samples_train)
    if (length(n_samples) != 1L || is.na(n_samples) || n_samples <
        1L) {
        stop("Invalid training sample count.", call. = FALSE)
    }
    max_sgd <- max(1L, analysis2_as_int(n_sgd))
    max(1L, min(analysis2_as_int(default), max_sgd))
}, analysis2_multidisease_structured_control_globals <- function(spec,
    n_samples_train, n_sgd) {
    if (!is.list(spec)) {
        stop("`spec` must be a normalized multidisease run specification.",
            call. = FALSE)
    }
    n_checkpoints_default <- analysis2_as_int(spec$n_checkpoints)
    prior_sd_multiplier <- suppressWarnings(as.numeric(spec$prior_sd_multiplier))
    if (length(n_checkpoints_default) != 1L || is.na(n_checkpoints_default) ||
        n_checkpoints_default < 1L) {
        stop("`n_checkpoints` must be one positive integer.",
            call. = FALSE)
    }
    if (length(prior_sd_multiplier) != 1L || !is.finite(prior_sd_multiplier) ||
        prior_sd_multiplier <= 0) {
        stop("`prior_sd_multiplier` must be one finite positive value.",
            call. = FALSE)
    }
    compute_backend <- match.arg(tolower(as.character(spec$compute_backend %||%
        "auto")), c("auto", "cpu", "gpu"))
    resolved_n_sgd <- max(1L, analysis2_as_int(n_sgd))
    list(nCheckpointsDefault = n_checkpoints_default, nCheckpoints = analysis2_small_run_n_checkpoints(n_samples_train,
        resolved_n_sgd, n_checkpoints_default), PriorSDMultiplier = prior_sd_multiplier,
        computeBackend = compute_backend, compute_backend = compute_backend,
        force2GPU = identical(compute_backend, "gpu"), GPU_MEM_FRAC = spec$gpu_mem_frac,
        nSGD_DefiningLRSeq = resolved_n_sgd, nSGD_model = resolved_n_sgd,
        nSGD_posttrain = resolved_n_sgd)
}, analysis2_small_run_n_obs_inference <- function(n_samples_train,
    n_batch, configured = NULL, default = 1024L) {
    if (!is.null(configured) && !is.na(configured) && configured >
        0L) {
        return(analysis2_as_int(configured))
    }
    n_samples <- max(1L, analysis2_as_int(n_samples_train))
    if (n_samples < 32L) {
        return(max(32L, as.integer(8L * max(1L, analysis2_as_int(n_batch)))))
    }
    analysis2_as_int(default)
}, analysis2_resolve_nsgd_calibration <- function(mode, spec,
    grid, n_epoches_max, fallback_n_samples_train = NULL) {
    resolver <- utils::getFromNamespace(".ndm_resolve_nsgd_calibration",
        "ndm")
    calibration <- tryCatch(resolver(mode = mode, project_root = spec$project_root,
        analysis_name = spec$analysis_name, n_epoches_max = n_epoches_max,
        grid = grid, grid_file = spec$grid_file, fallback_n_samples_train = fallback_n_samples_train),
        error = function(e) {
            missing_anchor_msg <- "Unable to resolve an nSGD calibration anchor because no candidate grid with `nSamplesTrain` was found"
            if (isTRUE(spec$dry_run) && grepl(missing_anchor_msg,
                conditionMessage(e), fixed = TRUE)) {
                return(NULL)
            }
            stop(e)
        })
    if (!is.null(calibration) && !is.null(spec$max_sgd_steps)) {
        calibration$unbounded_resolved_n_sgd <- calibration$resolved_n_sgd
        calibration$resolved_n_sgd <- min(as.integer(calibration$resolved_n_sgd),
            as.integer(spec$max_sgd_steps))
        calibration$policy <- paste0(calibration$policy, "+pilot_cap")
    }
    calibration
}, analysis2_nsgd_calibration_globals <- function(calibration) {
    globals_fun <- utils::getFromNamespace(".ndm_nsgd_calibration_globals",
        "ndm")
    globals_fun(calibration)
}, analysis2_log_nsgd_calibration <- function(mode, calibration) {
    formatter <- utils::getFromNamespace(".ndm_nsgd_calibration_message",
        "ndm")
    analysis2_log(formatter(mode, calibration))
}, analysis2_parse_bool <- function(x, field = NULL) {
    if (is.null(x)) {
        return(NULL)
    }
    if (is.logical(x) && length(x) == 1L && !is.na(x)) {
        return(x)
    }
    if (is.character(x) && length(x) == 1L && !is.na(x)) {
        value <- tolower(trimws(x))
        if (value %in% c("true", "t", "1", "yes", "y")) {
            return(TRUE)
        }
        if (value %in% c("false", "f", "0", "no", "n")) {
            return(FALSE)
        }
    }
    label <- if (is.null(field))
        "Logical value"
    else paste0("`", field, "`")
    stop(label, " must be one non-missing logical value or canonical logical spelling.",
        call. = FALSE)
}, analysis2_compute_backend <- function(compute_backend = NULL,
    force_to_gpu = NULL, compute_backend_supplied = !is.null(compute_backend)) {
    compute_backend_supplied <- isTRUE(compute_backend_supplied)
    if (!is.null(force_to_gpu)) {
        force_to_gpu <- analysis2_parse_bool(force_to_gpu, field = "force_to_gpu")
    }
    compute_backend <- tolower(analysis2_normalize_string(compute_backend) %||%
        "auto")
    if (!compute_backend %in% c("auto", "cpu", "gpu")) {
        stop("`compute_backend` must be one of \"auto\", \"cpu\", or \"gpu\".",
            call. = FALSE)
    }
    if (!is.null(force_to_gpu)) {
        legacy_backend <- if (isTRUE(force_to_gpu))
            "gpu"
        else "cpu"
        if (!isTRUE(compute_backend_supplied)) {
            compute_backend <- legacy_backend
        }
        else if (!identical(compute_backend, legacy_backend)) {
            stop("`force_to_gpu` conflicts with `compute_backend`; use the canonical compute policy.",
                call. = FALSE)
        }
    }
    compute_backend
}, analysis2_parse_args <- function(args = commandArgs(TRUE)) {
    out <- list(positional = character())
    for (arg in args) {
        if (!startsWith(arg, "--")) {
            out$positional <- c(out$positional, arg)
            next
        }
        arg <- sub("^--", "", arg)
        pieces <- strsplit(arg, "=", fixed = TRUE)[[1]]
        key <- gsub("-", "_", pieces[[1]])
        value <- if (length(pieces) > 1L) {
            paste(pieces[-1], collapse = "=")
        }
        else {
            "TRUE"
        }
        out[[key]] <- value
    }
    for (name in c("dry_run", "run_figures", "respect_grid_model_type",
        "resave_tfrecords", "force_to_gpu", "enable_kv_cache",
        "enable_kv_cache_training", "neuralode_variational",
        "help")) {
        if (!is.null(out[[name]])) {
            out[[name]] <- analysis2_parse_bool(out[[name]])
        }
    }
    out
}, analysis2_normalize_string <- function(x) {
    if (is.null(x)) {
        return(NULL)
    }
    value <- trimws(as.character(x[[1]]))
    if (!nzchar(value) || tolower(value) %in% c("null", "na")) {
        return(NULL)
    }
    value
}, analysis2_parse_csv <- function(x) {
    if (is.null(x)) {
        return(NULL)
    }
    if (is.list(x)) {
        x <- unlist(x, recursive = TRUE, use.names = FALSE)
    }
    if (length(x) > 1L) {
        out <- trimws(as.character(x))
    }
    else {
        out <- trimws(strsplit(as.character(x), ",", fixed = TRUE)[[1]])
    }
    out[nzchar(out)]
}, analysis2_as_flag <- function(x) {
    if (is.null(x)) {
        return(NULL)
    }
    analysis2_parse_bool(x)
}, analysis2_supported_flags <- function(mode) {
    base <- c("config", "project_root", "analysis_name", "grid_file",
        "outer", "run_seed", "compute_backend", "force_to_gpu",
        "gpu_mem_frac", "enable_kv_cache", "enable_kv_cache_training",
        "inference_mc_draws", "observation_scale_floor", "initial_observation_scale",
        "neuralode_variational", "neuralode_kl_weight", "neuralode_mean_loss_weight",
        "training_objective", "outcome_loss_scale", "n_checkpoints",
        "max_sgd_steps", "prior_sd_multiplier", "solver_profile",
        "model_type", "respect_grid_model_type", "resave_tfrecords",
        "run_figures", "tfrecord_dir", "dry_run", "help")
    extras <- switch(mode, real = c("raw_data_dir", "outcome_metric",
        "data_subset"), sim = character(), multidisease = c("outcome_metric",
        "data_subset", "disease_names", "data_format", "covariate_panel_file",
        "covariate_manifest_file"), stop("Unsupported Analysis2 mode: ",
        mode, call. = FALSE))
    unique(c(base, extras))
}, analysis2_validate_args <- function(opts, mode) {
    known <- analysis2_supported_flags(mode)
    present <- setdiff(names(opts), "positional")
    unknown <- setdiff(present, known)
    if (length(unknown) == 0L) {
        return(invisible(opts))
    }
    stop("Unknown option(s) for Analysis2 ", mode, " runs: ",
        paste(sprintf("--%s", gsub("_", "-", unknown)), collapse = ", "),
        ". Use `--help` to inspect the supported interface.",
        call. = FALSE)
}, analysis2_validate_manifest <- function(manifest, mode) {
    if (length(manifest) == 0L) {
        return(invisible(manifest))
    }
    known <- names(analysis2_mode_defaults(mode))
    unknown <- setdiff(names(manifest), c(known, "config_file",
        "paths"))
    if (length(unknown) > 0L) {
        stop("Unknown config field(s) in the Analysis2 ", mode,
            " manifest: ", paste(unknown, collapse = ", "), ".",
            call. = FALSE)
    }
    boolean_fields <- intersect(c("respect_grid_model_type",
        "resave_tfrecords", "run_figures", "force_to_gpu", "enable_kv_cache",
        "enable_kv_cache_training", "neuralode_variational",
        "dry_run", "help"), names(manifest))
    for (field in boolean_fields) {
        analysis2_parse_bool(manifest[[field]], field = field)
    }
    analysis2_compute_backend(manifest$compute_backend, manifest$force_to_gpu,
        compute_backend_supplied = "compute_backend" %in% names(manifest))
    invisible(manifest)
}, analysis2_default_config_name <- function(mode) {
    switch(mode, real = "real.yaml", sim = "sim.yaml", multidisease = "real_multidisease.yaml",
        stop("Unsupported Analysis2 mode: ", mode, call. = FALSE))
}, analysis2_require_yaml <- function() {
    if (!requireNamespace("yaml", quietly = TRUE)) {
        stop("The `yaml` package is required for Analysis2 config manifests.",
            call. = FALSE)
    }
    "yaml"
}, analysis2_load_yaml_config <- function(path) {
    if (is.null(path) || !file.exists(path)) {
        return(list())
    }
    if (!requireNamespace("yaml", quietly = TRUE)) {
        stop("The `yaml` package is required when `config` points to a YAML manifest.",
            call. = FALSE)
    }
    config <- yaml::read_yaml(path)
    if (is.null(config)) {
        return(list())
