}, analysis2_resolve_outer_iterations <- function(opts, default) {
    raw <- opts$outer %||% if (length(opts$positional) > 0L)
        opts$positional[[1]]
    else NULL
    if (is.null(raw) || !nzchar(raw)) {
        return(as.integer(default))
    }
    parts <- strsplit(as.character(raw), ",", fixed = TRUE)[[1]]
    as.integer(trimws(parts))
}, analysis2_row_to_list <- function(row) {
    stopifnot(nrow(row) == 1L)
    out <- vector("list", length = ncol(row))
    names(out) <- names(row)
    for (name in names(row)) {
        value <- row[[name]][[1]]
        numeric_value <- suppressWarnings(analysis2_f2n(value))
        out[[name]] <- if (!is.na(numeric_value))
            numeric_value
        else as.character(value)
    }
    out
}, analysis2_scalar_df <- function(values) {
    as.data.frame(values, stringsAsFactors = FALSE, check.names = FALSE)
}, analysis2_order_grid <- function(grid, outer_iterations) {
    if ("row_id" %in% names(grid)) {
        row_ids <- trimws(as.character(grid$row_id))
        if (anyNA(grid$row_id) || any(!nzchar(row_ids)) || anyDuplicated(row_ids)) {
            stop("Grid `row_id` values must be non-missing and unique.",
                call. = FALSE)
        }
    }
    grid
}, analysis2_validate_outer_iterations <- function(grid, outer_iterations,
    grid_file) {
    if (length(outer_iterations) == 0L) {
        stop("No outer iterations were requested.", call. = FALSE)
    }
    bad <- outer_iterations[is.na(outer_iterations) | outer_iterations <
        1L | outer_iterations > nrow(grid)]
    if (length(bad) == 0L) {
        return(invisible(outer_iterations))
    }
    stop("Requested outer iteration(s) outside the grid bounds for ",
        grid_file, ": ", paste(bad, collapse = ", "), ". Valid rows are between 1 and ",
        nrow(grid), ".", call. = FALSE)
}, analysis2_validate_process_float_type <- function(grid, outer_iterations,
    grid_file) {
    if (!"floatType" %in% names(grid)) {
        stop("Grid is missing required `floatType`: ", grid_file,
            call. = FALSE)
    }
    values <- trimws(as.character(grid$floatType[outer_iterations]))
    if (anyNA(values) || any(!values %in% c("32", "64"))) {
        stop("Selected grid rows must use `floatType` 32 or 64 in ",
            grid_file, ".", call. = FALSE)
    }
    unique_values <- unique(values)
    if (length(unique_values) != 1L) {
        stop("One Analysis2 run/process must use exactly one `floatType`; selected rows in ",
            grid_file, " contain: ", paste(unique_values, collapse = ", "),
            ". Split mixed-precision rows into separate processes.",
            call. = FALSE)
    }
    invisible(unique_values[[1L]])
}, analysis2_require_ndm <- function() {
    pkg <- tryCatch(utils::packageName(), error = function(e) NULL)
    if (!is.null(pkg) && nzchar(pkg)) {
        return(pkg)
    }
    "ndm"
}, analysis2_require_ndmdatasets <- function() {
    if (requireNamespace("ndmdatasets", quietly = TRUE)) {
        return("ndmdatasets")
    }
    stop("The `ndmdatasets` package is required. Install it before running Analysis2.",
        call. = FALSE)
}, analysis2_backend_conda_env <- function() {
    env_name <- Sys.getenv("NDM_SOFTWARE_CONDA_ENV", unset = "")
    if (nzchar(env_name)) {
        return(env_name)
    }
    env_name <- Sys.getenv("NDM_CONDA_ENV", unset = "")
    if (nzchar(env_name)) {
        return(env_name)
    }
    if (grepl(version$os, pattern = "darwin")) {
        return("jax_cpu")
    }
    "ndm_software_env"
